import{_ as t,o as a,a as i,b as l}from"./app.C41L12d5.js";const c=JSON.parse('{"title":"","description":"","frontmatter":{"breadcrumbs":[{"text":"Ascend C算子开发指南","link":"/guide/getting_started/ascend_c_overview_and_learning_path"},{"text":"编程指南","link":"/guide/programming_guide/document_structure"},{"text":"高级编程","link":"/guide/programming_guide/advanced_programming/advanced_programming"},{"text":"Aclnn算子工程化开发","link":"/guide/programming_guide/advanced_programming/aclnn_operator_development/overview"},{"text":"概述","link":"/guide/programming_guide/advanced_programming/aclnn_operator_development/overview"}]},"headers":[],"relativePath":"guide/programming_guide/advanced_programming/aclnn_operator_development/overview.md","filePath":"guide/programming_guide/advanced_programming/aclnn_operator_development/overview.md","outlineHeaders":[{"level":2,"title":"什么是工程化算子开发","slug":"什么是工程化算子开发","link":"#什么是工程化算子开发"},{"level":3,"title":"关键术语","slug":"关键术语","link":"#关键术语"},{"level":3,"title":"工程化开发是什么","slug":"工程化开发是什么","link":"#工程化开发是什么"},{"level":3,"title":"集成方式","slug":"集成方式","link":"#集成方式"},{"level":2,"title":"推荐阅读路径","slug":"推荐阅读路径","link":"#推荐阅读路径"},{"level":3,"title":"设计与实现","slug":"设计与实现","link":"#设计与实现"},{"level":3,"title":"编译与部署","slug":"编译与部署","link":"#编译与部署"},{"level":3,"title":"调用验证","slug":"调用验证","link":"#调用验证"},{"level":3,"title":"参考文档","slug":"参考文档","link":"#参考文档"}],"lastUpdated":1787886219000}'),n={name:"guide/programming_guide/advanced_programming/aclnn_operator_development/overview.md"};function r(d,e,o,_,m,p){return a(),i("div",null,[...e[0]||(e[0]=[l('<div><article class="markdown-body"><h1>概述</h1><p>本文是基础内容，说明Aclnn算子工程化开发这组文档的范围、阅读顺序和前置条件。建议先确认环境满足要求，再按<a href="./aclnn_quick_start.html">快速入门</a>跑通AddCustom示例，跑通后回到对应章节逐步补齐细节。</p><h2 id="什么是工程化算子开发">什么是工程化算子开发<a class="header-anchor" href="#什么是工程化算子开发">​</a></h2><h3 id="关键术语">关键术语<a class="header-anchor" href="#关键术语">​</a></h3><p>先介绍几个核心概念：</p><table><thead><tr><th>名称</th><th>含义</th></tr></thead><tbody><tr><td>自定义算子工程</td><td>根据算子原型定义编写或者生成的工程骨架，包含原型定义、Tiling实现、核函数（Kernel）实现和CMake编译配置。</td></tr><tr><td>算子原型</td><td>描述算子的输入、输出、属性、数据类型、格式、Shape推导等信息。</td></tr><tr><td>Host侧</td><td>运行在CPU侧的准备逻辑，例如Shape推导、Tiling计算、workspace大小设置。</td></tr><tr><td>核函数（Kernel）侧</td><td>运行在AI Core上的计算逻辑，是算子真正执行计算的部分。</td></tr><tr><td>Tiling</td><td>根据输入Shape、数据类型等信息切分计算任务，并把核函数（Kernel）需要的参数传递到核函数（Kernel）侧。</td></tr><tr><td>aclnn单算子API</td><td>算子工程编译后基于算子原型自动生成的C语言API，应用程序可通过该接口直接调用自定义算子。</td></tr></tbody></table><h3 id="工程化开发是什么">工程化开发是什么<a class="header-anchor" href="#工程化开发是什么">​</a></h3><p>工程化算子开发是指基于<strong>自定义算子工程</strong>完成算子实现、编译部署和调用验证的开发方式，主要面向CANN相关场景对接：单算子调用场景通过aclnn API完成接入，算子入图场景通过GE图执行链路完成接入。通过工程化开发，算子原型、Host侧Tiling、核函数（Kernel）实现和编译部署配置可以在两类场景中最大化复用同一份交付件。相比手动组织编译流程和分别对接调用链路，工程化开发由msOpGen生成工程骨架，CMake管理编译，编译产物自动包含aclnn API以及入图所需的原型定义等文件，部署时只需安装.run包或者链接静态/动态库。</p><h3 id="集成方式">集成方式<a class="header-anchor" href="#集成方式">​</a></h3><p>围绕同一份算子工程，常见集成方式如下：</p><table><thead><tr><th>集成方式</th><th>说明</th><th>适用场景</th></tr></thead><tbody><tr><td>单算子API调用</td><td>通过生成的aclnn接口直接调用算子，基于C语言API执行算子。</td><td>算子功能验证、单算子调用。</td></tr><tr><td>算子入图</td><td>补充Shape推导等入图适配代码后，基于GE图执行链路执行自定义算子。</td><td>图模式、IR构图、多算子组合。</td></tr><tr><td>AI框架调用</td><td>在工程化算子基础上增加框架插件适配后，通过PyTorch/TensorFlow等框架调用自定义算子。</td><td>融入AI训练或推理流程。</td></tr></tbody></table><h2 id="推荐阅读路径">推荐阅读路径<a class="header-anchor" href="#推荐阅读路径">​</a></h2><p>首次接触建议从<a href="./aclnn_quick_start.html">快速入门</a>开始，先用5分钟跑通AddCustom算子的端到端流程。跑通后再按以下路径逐步补齐细节。</p><p>本指南按开发流程组织为设计与实现、编译与部署、调用验证和参考文档。首次阅读只需关注<code>[基础]</code>文档，遇到具体问题时再查阅<code>[扩展]</code>文档。</p><h3 id="设计与实现">设计与实现<a class="header-anchor" href="#设计与实现">​</a></h3><p><code>[基础]</code>（按顺序阅读）：</p><ul><li><a href="./design_and_implementation/operator_function_design.html">算子功能设计</a> — 支持范围、场景划分、核函数（Kernel）组织。</li><li><a href="./design_and_implementation/operator_prototype_definition.html">算子原型定义</a> — 输入输出属性定义、Shape推导。</li><li><a href="./design_and_implementation/host_tiling_implementation.html">Host侧Tiling实现</a> — Tiling函数与数据结构、使用约束。</li><li><a href="./design_and_implementation/kernel_operator_implementation.html">核函数（Kernel）侧算子实现</a> — 核函数（Kernel）编程与API使用。</li></ul><p><code>[扩展]</code>（遇到具体问题时查阅）：</p><ul><li><a href="./design_and_implementation/tiling_data_attributes.html">通过TilingData传递属性信息</a> — 适用于算子属性需要传递到核函数（Kernel）侧的场景。</li><li><a href="./design_and_implementation/multi_branch_strategy.html">多分支策略</a> — 适用于算子需要按场景拆分核函数（Kernel）入口的场景。</li><li><a href="./design_and_implementation/gen_simplified_key.html">GenSimplifiedKey回调实现</a> — 适用于需要按自定义Key选择预编译binary的场景。</li><li><a href="./design_and_implementation/tiling_with_advanced_api.html">使用高阶API时配套的Tiling实现</a> — 适用于开发Matmul/Conv等复杂算子的场景。</li><li><a href="../operator_graph_development/enable_tiling_sink.html">开启Tiling下沉</a> — 适用于需要在算子入图场景开启Tiling下沉的场景。</li></ul><h3 id="编译与部署">编译与部署<a class="header-anchor" href="#编译与部署">​</a></h3><p><code>[基础]</code>：</p><ul><li><a href="./compilation_and_deployment/basic_process.html">编译与部署基本流程</a> — 编译配置、算子包打包与部署。</li></ul><p><code>[扩展]</code>：</p><ul><li><a href="./compilation_and_deployment/multi_operator_package.html">多算子包组织</a> — 多算子包拆分策略。</li><li><a href="./compilation_and_deployment/dynamic_static_lib_compilation.html">算子动态库和静态库编译</a> — 适用于需要以库形式集成到应用的场景。</li><li><a href="./compilation_and_deployment/cross_compilation.html">交叉编译</a> — 适用于开发环境与运行环境架构不同的场景。</li><li><a href="./compilation_and_deployment/compilation_debug.html">编译过程调试</a> — 适用于遇到编译问题的场景。</li><li><a href="./compilation_and_deployment/compilation_acceleration.html">编译加速</a> — 适用于需要加速构建的场景。</li><li><a href="./compilation_and_deployment/simplified_key_json_configuration.html">simplified key二进制配置JSON</a> — 适用于按自定义Key编译多份binary的场景。</li></ul><h3 id="调用验证">调用验证<a class="header-anchor" href="#调用验证">​</a></h3><p><code>[基础]</code>：</p><ul><li><a href="./invocation/single_operator_api_call.html">单算子API调用</a> — 通过aclnn API调用验证算子功能。</li></ul><p><code>[扩展]</code>：</p><ul><li><a href="./invocation/runtime_loading_mechanism.html">运行时加载机制</a> — 适用于需要了解二段式调用模型和代码写法如何影响运行表现的场景。</li><li><a href="./invocation/simplified_key_runtime_flow.html">基于simplified key的运行时选择流程</a> — 适用于需要了解运行时如何选择预编译binary的场景。</li></ul><h3 id="参考文档">参考文档<a class="header-anchor" href="#参考文档">​</a></h3><p>以下为查阅型内容，可在开发过程中按需检索：</p><ul><li><a href="./appendix/naming_conversion_table.html">命名转换规则对照表</a> — 算子类型名、文件名、核函数（Kernel）名的转换规则。</li><li><a href="./appendix/cmake_function_reference.html">cmake函数参考</a> — CMake函数的参数与用法详解。</li><li><a href="./appendix/external_sample_links.html">外部样例链接汇总</a> — 文档中引用的外部样例与API链接汇总。</li></ul></article></div>',1)])])}const s=t(n,[["render",r]]);export{c as __pageData,s as default};
